DO $$
DECLARE
  rec RECORD;
  cur_status VARCHAR(20);
  cur_mod_id INT;
  cur_esc_count INT;
BEGIN
  FOR rec IN SELECT * FROM moderation_events ORDER BY event_id LOOP
    SELECT status, assigned_moderator_id, escalation_count
      INTO cur_status, cur_mod_id, cur_esc_count
      FROM threads
     WHERE thread_id = rec.thread_id;

    IF rec.event_type = 1 AND cur_status = 'open' AND cur_mod_id IS NULL THEN
      UPDATE threads
         SET assigned_moderator_id = rec.moderator_id,
             status = 'under_review'
       WHERE thread_id = rec.thread_id;
    ELSIF rec.event_type = 2 AND cur_status = 'under_review' AND cur_mod_id = rec.moderator_id THEN
      UPDATE threads
         SET status = 'escalated',
             escalation_count = escalation_count + 1
       WHERE thread_id = rec.thread_id;
    ELSIF rec.event_type = 3 AND (cur_status = 'under_review' OR cur_status = 'escalated') THEN
      UPDATE threads
         SET status = 'closed'
       WHERE thread_id = rec.thread_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM threads ORDER BY thread_id;
